package io.github.phiscript.capture;import android.os.SystemClock;public class FrameStore {private int lastStage=-1,stageFrames;public CapturedFrame snapshot(){if(++CourseEngineRegression.frames>150)throw new AssertionError("course frame budget "+CourseEngineRegression.scenario);if(lastStage!=CourseEngineRegression.plays){lastStage=CourseEngineRegression.plays;stageFrames=0;}stageFrames++;SystemClock.now+=80;String s=CourseEngineRegression.scenario;int phase=stageFrames<=4?0:1;if(s.equals("nogap")||s.equals("continuous")&&CourseEngineRegression.plays>0)phase=1;if(CourseEngineRegression.pause)phase=2;if(CourseEngineRegression.result)phase=3;if(phase==1&&stageFrames==5)CourseEngineRegression.origin=SystemClock.now;if(s.equals("nosync")&&stageFrames>8)SystemClock.now+=2500;if((s.equals("ambiguous")||s.equals("nogap")||s.equals("stale"))&&CourseEngineRegression.frames>30)CourseEngineRegression.stop.set(true);return new CapturedFrame(phase,s.equals("stale")?SystemClock.now-1000:SystemClock.now);}}
